{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--card:#fff;--accent:#6c63ff;--muted:#6b7280;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial}
    body{background:linear-gradient(180deg,var(--bg),#f3f4f6);color:#111}
    .topbar{display:flex;align-items:center;justify-content:space-between;padding:18px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#9b8cff);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center;padding:28px}
    .hero-card{background:var(--card);border-radius:14px;padding:28px;box-shadow:0 6px 20px rgba(15,23,42,0.06)}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .cta{margin-top:16px;display:flex;gap:10px}
    .btn-primary{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;font-weight:700}
    .btn-ghost{background:transparent;border:1px solid #e6e7ee;padding:10px 12px;border-radius:10px;color:var(--muted)}
    .pattern-rail{height:100%;background-image:url('assets/img/pattern.svg');background-repeat:repeat;padding:24px;border-radius:12px}
    .programs{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 4px 14px rgba(12,18,30,0.04)}
    .price{font-size:22px;font-weight:800;color:var(--accent)}
    .meta{color:var(--muted);font-size:13px;margin-top:8px}
    .toggle{display:flex;align-items:center;gap:8px;margin-top:12px}
    .switch{width:56px;height:28px;background:#eef2ff;border-radius:999px;position:relative;padding:4px;cursor:pointer}
    .knob{width:20px;height:20px;background:white;border-radius:50%;position:absolute;top:4px;left:4px;transition:left .28s cubic-bezier(.2,.9,.2,1)}
    .knob.right{left:32px}
    .small{font-size:13px;color:var(--muted)}
    .proof{margin-top:22px}
    .testimonial{background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.9));padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.03)}
    .t-text{font-style:italic;color:#222}
    .t-author{margin-top:10px;font-weight:700}
    .badges{display:flex;gap:12px;margin-top:12px}
    .badge{background:#fff;padding:8px 12px;border-radius:999px;border:1px solid #eef2ff;cursor:default;position:relative}
    .badge:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:-36px;background:#111;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px;white-space:nowrap}
    footer{padding:26px;text-align:center;color:var(--muted)}
    @media (max-width:980px){.hero{grid-template-columns:1fr;}.programs{grid-template-columns:1fr}}  
  </style>
</head>
<body>
  <header class='topbar'>
    <div class='brand'>
      <div class='logo'>HM</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>Integrative cycles & guided programs</div>
      </div>
    </div>
    <nav>
      <a href='index.html'>Home</a>
      <a href='services.html' style='color:var(--accent)'>Offerings</a>
      <a href='conditions.html'>Conditions</a>
      <a href='approach.html'>Method</a>
      <a href='pricing.html'>Invest</a>
      <a href='about.html'>About</a>
      <a href='book.html'>Book</a>
      <a href='contact.html'>Contact</a>
    </nav>
  </header>

  <main class='hero'>
    <section class='hero-card'>
      <h1>Programs that treat context, not just the checklist</h1>
      <p class='lead'>We bundle learning, simpler rituals, and hands-on coaching so you can build better rhythms without fuss. Short cohorts, clear outcomes.</p>
      <div class='cta'>
        <a class='btn-primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
        <a class='btn-ghost' href='about.html'>Learn how we run cohorts</a>
      </div>
      <div class='proof'>
        <div class='testimonial' id='testimonial'>
          <div class='t-text' id='t-text'>“A thoughtful, practical partner for shifting daily patterns — not another to-do list.”</div>
          <div class='t-author' id='t-author'>— A participant in the Rhythm Program</div>
        </div>
        <div class='badges' id='badges'>
          <div class='badge' data-tip='Featured on a professional podcast'>Podcast Guest</div>
          <div class='badge' data-tip='Clinical trainings and CME credits offered'>Training Partner</div>
          <div class='badge' data-tip='Peer-reviewed case summaries available'>Case Reports</div>
        </div>
      </div>
    </section>

    <aside class='pattern-rail'>
      <div style='font-weight:700;margin-bottom:10px'>Choose your path</div>
      <div class='programs' id='programs'>
        <div class='card'>
          <div style='font-size:14px;color:var(--muted)'>Foundations Cycle</div>
          <div class='price' data-monthly='79' data-package='420'>$79/mo</div>
          <div class='meta'>6-week live cohort + journal prompts</div>
        </div>

        <div class='card'>
          <div style='font-size:14px;color:var(--muted)'>Rhythm Reset</div>
          <div class='price' data-monthly='149' data-package='840'>$149/mo</div>
          <div class='meta'>12-week guided cycle with 1:1 check-ins</div>
        </div>

        <div class='card'>
          <div style='font-size:14px;color:var(--muted)'>Revive Intensive</div>
          <div class='price' data-monthly='299' data-package='1600'>$299/mo</div>
          <div class='meta'>8-session intensive package tailored to complex cases</div>
        </div>
      </div>

      <div class='toggle'>
        <div class='small'>Show:</div>
        <div class='switch' id='priceSwitch' aria-pressed='false' role='switch' tabindex='0'>
          <div class='knob' id='knob'></div>
        </div>
        <div class='small' id='modeLabel'>Monthly</div>
      </div>

      <div style='margin-top:14px;font-size:13px;color:var(--muted)'>Prices shown are educational. Packages give a per-session discount and priority booking.</div>
    </aside>
  </main>

  <section style='padding:20px 28px'>
    <div style='display:flex;gap:18px;align-items:flex-start;flex-wrap:wrap'>
      <div style='flex:1;min-width:260px' class='card'>
        <div style='font-weight:700'>How cohorts work</div>
        <div style='color:var(--muted);margin-top:8px;font-size:14px'>Small groups, weekly lessons, a live session every other week, plus optional 1:1 check-ins. We blend evidence, lived experience, and practical experiments.</div>
      </div>

      <div style='width:340px' class='card'>
        <div style='font-weight:700'>Quick comparison</div>
        <div style='margin-top:8px;color:var(--muted);font-size:13px'>Toggle to see monthly vs package math. Numbers animate for clarity.</div>
        <div style='margin-top:12px;display:flex;flex-direction:column;gap:10px'>
          <div style='display:flex;justify-content:space-between'><span class='small'>Foundations</span><strong class='display-price' data-monthly='79' data-package='420'>$79/mo</strong></div>
          <div style='display:flex;justify-content:space-between'><span class='small'>Rhythm Reset</span><strong class='display-price' data-monthly='149' data-package='840'>$149/mo</strong></div>
          <div style='display:flex;justify-content:space-between'><span class='small'>Revive Intensive</span><strong class='display-price' data-monthly='299' data-package='1600'>$299/mo</strong></div>
        </div>
      </div>
    </div>
  </section>

  <footer>
    <div>Questions? Call <a href='tel:{{PHONE}}'>{{PHONE}}</a> or email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
    <div style='margin-top:8px;font-size:13px'>&copy; <span id='year'></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    // Proof gallery rotation
    (function(){
      const testimonials=[
        {text:'The cohort gave me a simple daily map I could follow; it stuck.',author:'M., 34'},
        {text:'Clear prompts and short live sessions — I finally unblocked my mornings.',author:'S., 42'},
        {text:'A practical way to shift habits without overwhelm.',author:'L., 29'}
      ];
      let idx=0;const tText=document.getElementById('t-text');const tAuthor=document.getElementById('t-author');
      function rotate(){idx=(idx+1)%testimonials.length;const t=testimonials[idx];tText.textContent='“'+t.text+'”';tAuthor.textContent='— '+t.author}
      setInterval(rotate,5000);
    })();

    // Pricing comparator with animated numbers
    (function(){
      const switchEl=document.getElementById('priceSwitch');const knob=document.getElementById('knob');const modeLabel=document.getElementById('modeLabel');
      let mode='monthly';
      function animateValue(el,from,to,duration){
        const start=performance.now();
        const isCurrency = String(to).indexOf('$')!==-1 || el.tagName==='STRONG' || el.classList.contains('price');
        const startN=Number(from);const endN=Number(to);
        function step(now){
          const t=Math.min(1,(now-start)/duration);
          const val=Math.round((endN-startN)*t+startN);
          el.textContent=(isCurrency?('$'+val):('$'+val))+(mode==='monthly'?'/mo':'');
          if(t<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function applyMode(){
        const priceEls=document.querySelectorAll('.price, .display-price');
        priceEls.forEach(el=>{
          const monthly=Number(el.getAttribute('data-monthly'))||0;
          const pack=Number(el.getAttribute('data-package'))||0;
          const fromText=(mode==='monthly')?pack:monthly;
          const toText=(mode==='monthly')?monthly:pack;
          animateValue(el,fromText,toText,420);
        });
      }

      switchEl.addEventListener('click',function(){
        mode = mode==='monthly'?'package':'monthly';
        const pressed = mode==='package';
        switchEl.setAttribute('aria-pressed', String(pressed));
        knob.classList.toggle('right', pressed);
        modeLabel.textContent = mode==='monthly'?'Monthly':'Package';
        applyMode();
      });

      // keyboard support
      switchEl.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' ') {e.preventDefault();switchEl.click();}});

      // init
      document.getElementById('year').textContent=new Date().getFullYear();
      applyMode();
    })();
  </script>
</body>
</html>"} 
