{"path":"approach.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Method & Philosophy — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f8fb;--accent:#ff6b6b;--muted:#475569}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#0f1724}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:#fff;border-bottom:1px solid #eef2f6}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .container{max-width:980px;margin:24px auto;padding:0 18px}
    .lead{display:flex;gap:18px;align-items:flex-start}
    .pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
    .pillar{background:#fff;padding:14px;border-radius:10px;border:1px solid #f0f3f8}
    .case{background:#fff;padding:12px;border-radius:10px;margin-top:12px;border:1px solid #f0f3f8}
    .muted{color:var(--muted)}
    .mini-cta{display:inline-block;background:var(--accent);color:white;padding:9px 12px;border-radius:10px;text-decoration:none;font-weight:700}
    .comparator{margin-top:18px;background:#fff;padding:12px;border-radius:10px;border:1px solid #f0f3f8}
    .footnote{font-size:13px;color:#7a8899;margin-top:10px}
    @media (max-width:900px){.pillars{grid-template-columns:1fr}}  
  </style>
</head>
<body>
  <header>
    <div style='font-weight:800'>{{BUSINESS_NAME}}</div>
    <nav>
      <a href='index.html'>Home</a>
      <a href='services.html'>Offerings</a>
      <a href='conditions.html'>Conditions</a>
      <a href='approach.html' style='color:var(--accent)'>Method</a>
      <a href='book.html'>Book</a>
    </nav>
  </header>

  <main class='container'>
    <section class='lead'>
      <div style='flex:1'>
        <h1 style='margin:0'>We design practical experiments, not prescriptions</h1>
        <p class='muted' style='margin-top:8px'>Our method blends a few reliable practices — personalized, measurable, and reversible. We call them the Three Threads.</p>
        <div style='margin-top:12px'>
          <a href='book.html' class='mini-cta'>Start a brief intake</a>
        </div>
      </div>

      <aside style='width:320px'>
        <div class='comparator'>
          <div style='font-weight:700'>Pricing snapshot</div>
          <div style='color:var(--muted);margin-top:8px;font-size:13px'>Toggle to compare a monthly subscription vs a one-time package. Numbers animate to show real difference.</div>
          <div style='display:flex;justify-content:space-between;margin-top:12px'>
            <div class='muted'>Subscription</div>
            <div class='muted'>Package</div>
          </div>
          <div style='display:flex;justify-content:space-between;margin-top:10px'>
            <div style='font-weight:800' id='subPrice'>$149/mo</div>
            <div style='font-weight:800' id='pkgPrice'>$840</div>
          </div>
          <div style='display:flex;gap:8px;margin-top:10px;align-items:center'>
            <button id='cmpToggle' style='padding:8px 10px;border-radius:8px;border:1px solid #eee;background:white;cursor:pointer'>Toggle</button>
            <div style='font-size:13px;color:var(--muted)'>Animate numbers</div>
          </div>
          <div class='footnote'>Package often reduces per-session cost and includes extra materials.</div>
        </div>
      </aside>
    </section>

    <section class='pillars' aria-label='Three Threads'>
      <div class='pillar'>
        <div style='font-weight:700'>Timing & Rhythm</div>
        <div class='muted' style='margin-top:8px'>We look at when things happen, then shape timing to fit biology and life. Small timing shifts can unlock big changes.</div>
      </div>

      <div class='pillar'>
        <div style='font-weight:700'>Feasible Actions</div>
        <div class='muted' style='margin-top:8px'>Every step must be doable. We split goals into micro-steps that stack toward lasting habits.</div>
      </div>

      <div class='pillar'>
        <div style='font-weight:700'>Measure & Iterate</div>
        <div class='muted' style='margin-top:8px'>Short cycles, clear signals, and quick refinements. If something doesn’t move, we change the experiment.</div>
      </div>
    </section>

    <section class='case'>
      <div style='font-weight:700'>Case note — an illustrative example</div>
      <div style='color:var(--muted);margin-top:8px'>A person with fragmented sleep and midday crashes tried a single timing change: light exposure within 30 minutes of waking and a small midafternoon walk. Over three weeks their average sleep continuity improved and naps decreased. This is an educational example, not a guaranteed outcome.</div>
    </section>

    <section style='margin-top:14px'>
      <div class='card' style='padding:14px'>
        <div style='font-weight:700'>Want the mechanics?</div>
        <div class='muted' style='margin-top:8px'>Cohorts include lesson modules, quick labs you can try at home, and optional 1:1 reviews to adjust experiments. We favor transparency: every recommendation is coupled with how we'll judge whether it helped.</div>
        <div style='margin-top:12px'><a href='services.html' class='mini-cta' style='background:#1f8ef1'>See current cohorts</a></div>
      </div>
    </section>

  </main>

  <footer style='padding:18px;text-align:center;color:#9aa4b2'>
    <div>Questions? Email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a> or call <a href='tel:{{PHONE}}'>{{PHONE}}</a></div>
  </footer>

  <script>
    // Simple comparator toggle with animated numbers
    (function(){
      const sub=document.getElementById('subPrice');const pkg=document.getElementById('pkgPrice');const btn=document.getElementById('cmpToggle');
      let showing='monthly';
      function animate(el,from,to,duration=500){
        const start=performance.now();const a=Number(from);const b=Number(to);
        function frame(now){
          const t=Math.min(1,(now-start)/duration);
          const v=Math.round(a + (b-a)*t);
          el.textContent = (el===pkg?('$'+v):('$'+v+'/mo'));
          if(t<1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }
      btn.addEventListener('click',function(){
        if(showing==='monthly'){ animate(sub,149,120,600); animate(pkg,840,720,600); showing='package'; }
        else{ animate(sub,120,149,600); animate(pkg,720,840,600); showing='monthly'; }
      });
    })();
  </script>
</body>
</html>"} 
